do $$
declare w uuid=gen_random_uuid();u uuid=gen_random_uuid();supplier uuid=gen_random_uuid();oid uuid=gen_random_uuid();save_id uuid=gen_random_uuid();receive_id uuid=gen_random_uuid();p shop_products;s shop_suppliers;doc jsonb;lines jsonb;recv jsonb;suggestions jsonb;retail_line uuid;pro_line uuid;bad boolean;other uuid=gen_random_uuid();begin
 insert into auth.users(id,email) values(u,u||'@example.invalid');
 insert into workspaces(id,salon_name,slug,owner_email,subscription_status,subscription_ends_at) values(w,'Purchasing fixture','purchasing-'||w,u||'@example.invalid','active',now()+interval '1 year');
 insert into workspace_members(workspace_id,user_id,email) values(w,u,u||'@example.invalid');perform set_config('request.jwt.claim.sub',u::text,true);
 perform shop_set_enabled(true,1);
 s=shop_supplier_save(supplier,0,'{"name":"Fornitore test","email":"fixture@example.invalid","lead_days":3}');perform shop_supplier_save(supplier,0,'{"name":"Fornitore test","email":"fixture@example.invalid","lead_days":3}');
 if (select count(*) from shop_suppliers where workspace_id=w)<>1 then raise exception 'Supplier retry duplicated';end if;
 p=shop_create_product(gen_random_uuid(),'{"name":"Shampoo","sku":"SUPPLY","purpose":"both","unit":"ml","pack_size":250,"price_cents":2000,"cost_cents":800,"minimum_retail":2,"minimum_professional":200}');
 perform shop_adjust_stock(gen_random_uuid(),p.id,'retail','receive',1,'Scorta iniziale',0);
 perform shop_reorder_save(p.id,0,supplier,6,1000);
 suggestions=shop_reorder_suggestions();
 if jsonb_array_length(suggestions->'items')<>2 or not exists(select 1 from jsonb_array_elements(suggestions->'items') x where x->>'bucket'='retail' and (x->>'suggested_packs')::int=5) or not exists(select 1 from jsonb_array_elements(suggestions->'items') x where x->>'bucket'='professional' and (x->>'suggested_packs')::int=4) then raise exception 'Incorrect reorder conversion';end if;
 lines=jsonb_build_array(jsonb_build_object('product_id',p.id,'bucket','retail','quantity',4,'unit_cost_cents',700,'product_revision',p.revision),jsonb_build_object('product_id',p.id,'bucket','professional','quantity',2,'unit_cost_cents',700,'product_revision',p.revision));
 doc=shop_purchase_save(save_id,oid,0,supplier,current_date+3,'Fixture',lines);perform shop_purchase_save(save_id,oid,0,supplier,current_date+3,'Fixture',lines);
 if (select count(*) from shop_purchase_lines where order_id=oid)<>2 then raise exception 'Duplicate draft';end if;
 if shop_reorder_suggestions()->>'count'<>'2' then raise exception 'Draft counted as incoming';end if;
 doc=shop_purchase_transition(oid,1,'ordered');perform shop_purchase_transition(oid,1,'ordered');
 if shop_reorder_suggestions()->>'count'<>'0' then raise exception 'Incoming ignored in suggestions';end if;
 if (select retail_qty from shop_products where id=p.id)<>1 or exists(select 1 from cash_movements where workspace_id=w) then raise exception 'Order changed stock or cash';end if;
 bad=false;begin perform shop_purchase_save(gen_random_uuid(),oid,2,supplier,current_date,'Invalid',lines);exception when others then bad=true;end;if not bad then raise exception 'Confirmed order edited';end if;
 s=shop_supplier_save(supplier,s.revision,'{"name":"Nuovo nome","email":"fixture@example.invalid","lead_days":3}');
 if shop_purchase_document(oid)->>'supplier_name'<>'Fornitore test' then raise exception 'Supplier snapshot rewritten';end if;
 select id into retail_line from shop_purchase_lines where order_id=oid and bucket='retail';select id into pro_line from shop_purchase_lines where order_id=oid and bucket='professional';
 recv=jsonb_build_array(jsonb_build_object('line_id',retail_line,'quantity',2),jsonb_build_object('line_id',pro_line,'quantity',1));
 doc=shop_purchase_receive(receive_id,oid,2,'DDT test 1',recv);perform shop_purchase_receive(receive_id,oid,2,'DDT test 1',recv);
 if doc->>'status'<>'partial' or (select retail_qty from shop_products where id=p.id)<>3 or (select professional_qty from shop_products where id=p.id)<>250 or (select count(*) from shop_purchase_receipts where order_id=oid)<>1 then raise exception 'Partial receipt or retry wrong';end if;
 bad=false;begin perform shop_purchase_receive(gen_random_uuid(),oid,2,'Stale',recv);exception when others then bad=true;end;if not bad then raise exception 'Stale receipt accepted';end if;
 bad=false;begin perform shop_purchase_receive(gen_random_uuid(),oid,3,'Excess',jsonb_build_array(jsonb_build_object('line_id',retail_line,'quantity',1),jsonb_build_object('line_id',pro_line,'quantity',20)));exception when others then bad=true;end;
 if not bad or (select retail_qty from shop_products where id=p.id)<>3 then raise exception 'Invalid multi-line receipt partially committed';end if;
 perform shop_set_enabled(false,2);doc=shop_purchase_receive(gen_random_uuid(),oid,3,'DDT test 2',recv);
 if doc->>'status'<>'received' or (select retail_qty from shop_products where id=p.id)<>5 or (select professional_qty from shop_products where id=p.id)<>500 then raise exception 'Final receipt wrong';end if;
 if exists(select 1 from cash_movements where workspace_id=w) then raise exception 'Receipt creates financial transaction';end if;
 perform shop_set_enabled(true,3);oid=gen_random_uuid();doc=shop_purchase_save(gen_random_uuid(),oid,0,supplier,null,'Residuo',lines);doc=shop_purchase_transition(oid,1,'ordered');
 select id into retail_line from shop_purchase_lines where order_id=oid and bucket='retail';doc=shop_purchase_receive(gen_random_uuid(),oid,2,'Parziale',jsonb_build_array(jsonb_build_object('line_id',retail_line,'quantity',1)));doc=shop_purchase_transition(oid,3,'closed');
 if doc->>'status'<>'closed' or (select retail_qty from shop_products where id=p.id)<>6 then raise exception 'Closing remainder changes delivered stock';end if;
 bad=false;begin perform shop_purchase_receive(gen_random_uuid(),oid,4,'After close',recv);exception when others then bad=true;end;if not bad then raise exception 'Closed order accepted delivery';end if;
 insert into workspaces(id,salon_name,slug,owner_email,subscription_status) values(other,'Foreign fixture','foreign-'||other,'foreign@example.invalid','active');
 insert into shop_suppliers(id,workspace_id,name) values(gen_random_uuid(),other,'Foreign') returning id into supplier;
 bad=false;begin perform shop_supplier_save(supplier,0,'{"name":"Attack"}');exception when others then bad=true;end;if not bad then raise exception 'Foreign supplier overwritten';end if;
 insert into shop_purchase_orders(id,workspace_id,supplier_id,supplier_name,supplier_email,created_by) values(gen_random_uuid(),other,supplier,'Foreign','',u) returning id into oid;
 select id into supplier from shop_suppliers where workspace_id=w limit 1;
 bad=false;begin perform shop_purchase_save(gen_random_uuid(),oid,0,supplier,null,'Attack',lines);exception when others then bad=true;end;if not bad then raise exception 'Foreign order overwritten';end if;
 if has_function_privilege('anon','shop_purchase_receive(uuid,uuid,integer,text,jsonb)','EXECUTE') or has_table_privilege('authenticated','shop_purchase_lines','UPDATE') then raise exception 'Excess privileges';end if;
 perform set_config('request.jwt.claim.sub',gen_random_uuid()::text,true);bad=false;begin perform shop_supply_console();exception when others then bad=true;end;if not bad then raise exception 'Unauthorised supplier read';end if;
end $$;
